  <SectionCard className="pb-4">
    <SectionCard.Header title="Labels & Annotations" />
    <SectionCard.Content>
      <VStack gap={6}>
        <FormField label="Labels">
          <Input placeholder="e.g. app=my-service" fullWidth />
        </FormField>
      </VStack>
    </SectionCard.Content>
  </SectionCard>
